/// <summary>
/// The NVTrvWorkerExpenseReqApprovalResubmitActionMgr menu item action event handler.
/// </summary>
public class NVTrvWorkerExpenseReqApprovalResubmitActionMgr 
{
    Args args;

}

Method.Source:
protected Args parmArgs(Args _args = args)
{
    args = _args;
    return args;
}

protected void run()
{
    RecId                           recID               = args.record().RecId;
    tableId                         tableId             = args.record().TableId;
    NVTrvWorkerExpenseRequest       requestTable        = args.record();
    WorkflowWorkItemTable           workItem            = args.caller().getActiveWorkflowWorkItem();
    WorkflowWorkItemActionDialog    workflowWorkItemActionDialog;

    if (tableId != tablenum(NVTrvWorkerExpenseRequest) ||
        recId == 0)
    {
        throw error(strfmt("@SYS19306", funcname()));
    }

    if (workItem.RecId > 0)
    {
        workflowWorkItemActionDialog = WorkflowWorkItemActionDialog::construct( workItem,
                                                                                WorkflowWorkItemActionType::Resubmit,
                                                                                new MenuFunction(args.menuItemName(), args.menuItemType()));
        workflowWorkItemActionDialog.run();

        if (workflowWorkItemActionDialog.parmIsClosedOK())
        {
            workItem    = args.caller().getActiveWorkflowWorkItem();
            WorkflowWorkItemActionManager::dispatchWorkItemAction(workItem,
                                                workflowWorkItemActionDialog.parmWorkflowComment(),
                                                workflowWorkItemActionDialog.parmTargetUser(),
                                                WorkflowWorkItemActionType::Resubmit,
                                                args.menuItemName());

            NVTrvWorkerExpenseRequest::updateWorkflowStatus(recID, NVTrvWorkerExpReqWFStatus::Submitted);
        }
    }
    // Make the form refresh its common workflow UI controls.
    args.caller().updateWorkflowControls();

    Object callerForm = args.caller();
    FormDataSource fds = args.record().datasource();
    if(callerForm)
    {
        fds.refresh();
        fds.research(true);
    }
}

public static void main(Args _args)
{
    NVTrvWorkerExpenseReqApprovalResubmitActionMgr resubmit = new NVTrvWorkerExpenseReqApprovalResubmitActionMgr();
    resubmit.parmArgs(_args);
    resubmit.run();
}
